// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface RepeatIn {
  reason: "Positioning" | "PatientMotion" | "ExposureFactors" | "Artefact" | "EquipmentFault" | "ProcessingError" | "WrongPatientOrSite" | "Other";
  /** How many exposures were repeated */
  exposures?: number;
  /** Required for Other */
  note?: string | null;
}

export interface RepeatOut {
  repeat_id: number;
  imaging_order_id: number;
  order_number: string;
  modality: "XRay" | "MRI" | "CT" | "Ultrasound" | "Doppler" | "Mammography" | "Fluoroscopy" | "Other";
  body_part: string | null;
  reason: "Positioning" | "PatientMotion" | "ExposureFactors" | "Artefact" | "EquipmentFault" | "ProcessingError" | "WrongPatientOrSite" | "Other";
  exposures: number;
  note: string | null;
  recorded_by: number;
  recorded_by_name: string;
  recorded_at: string;
  patient_name: string;
  mrn: string;
}

/** Record a repeated exposure — POST /api/v1/imaging/orders/{order_id}/repeats (who may call: holders of imaging.order.update). */
export function recordRepeat(order_id: number, body: RepeatIn): Promise<RepeatOut> {
  return api<RepeatOut>("POST", `/imaging/orders/${order_id}/repeats`, body, { idempotent: true });
}

/** The register of repeated images — GET /api/v1/imaging/repeats (who may call: holders of imaging.order.update or diagnostics.quality.view). */
export function listRepeats(query: { date_from: string; date_to: string; modality?: "XRay" | "MRI" | "CT" | "Ultrasound" | "Doppler" | "Mammography" | "Fluoroscopy" | "Other" | null }): Promise<RepeatOut[]> {
  return api<RepeatOut[]>("GET", withQuery(`/imaging/repeats`, query), undefined);
}
